commands.command:
install -d -m 0755 /var/www/inventory
cat > /var/www/inventory/index.html <<'ANTRIEB_HTML'
<!doctype html>
<html><head><meta charset="utf-8"><title>Inventory</title></head>
<body><h1>Inventory Web Application</h1><p>Served by <strong>node2</strong></p>
<table border="1"><thead><tr><th>SKU</th><th>Item</th><th>Quantity</th></tr></thead>
<tbody><tr><td>INV-1001</td><td>Widget</td><td>42</td></tr><tr><td>INV-1002</td><td>Gadget</td><td>17</td></tr></tbody></table></body></html>
ANTRIEB_HTML
cat > /etc/nginx/sites-available/inventory <<'ANTRIEB_NGINX'
server {
    listen 0.0.0.0:8080 default_server;
    listen [::]:8080 default_server;
    server_name _;
    root /var/www/inventory;
    index index.html;
    add_header X-Backend node2 always;

    location = /health {
        access_log off;
        default_type text/plain;
        return 200 "healthy node2\n";
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}
ANTRIEB_NGINX
ln -sfn /etc/nginx/sites-available/inventory /etc/nginx/sites-enabled/inventory
rm -f /etc/nginx/sites-enabled/default
nginx -t && systemctl enable nginx && systemctl restart nginx

