cat > /etc/nginx/sites-available/inventory-lb <<'ANTRIEB_NGINX'
upstream inventory_backends {
    server 10.100.11.11:8080 max_fails=2 fail_timeout=5s;
    server 10.100.11.12:8080 max_fails=2 fail_timeout=5s;
}

server {
    listen 0.0.0.0:80 default_server;
    listen [::]:80 default_server;
    server_name _;

    add_header X-Load-Balancer node1 always;

    location / {
        proxy_pass http://inventory_backends;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_next_upstream error timeout http_502 http_503 http_504;
    }
}
ANTRIEB_NGINX
ln -sfn /etc/nginx/sites-available/inventory-lb /etc/nginx/sites-enabled/inventory-lb
rm -f /etc/nginx/sites-enabled/default
nginx -t && systemctl enable nginx && systemctl restart nginx
